using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

namespace McpServer;

/// <summary>
/// MCP tool class wrapping a weather REST API.
/// The MCP SDK discovers methods decorated with [McpServerTool].
/// Constructor parameters are resolved via DI automatically.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves this via DI — registered HttpClient is injected here.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city. Returns temperature and conditions.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle' or 'London'")] string city,
        CancellationToken cancellationToken = default)
    {
        // Example using Open-Meteo geocoding + forecast (no API key needed)
        var geoUrl = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var geoResponse = await _httpClient.GetFromJsonAsync<JsonDocument>(geoUrl, cancellationToken);

        var results = geoResponse?.RootElement.GetProperty("results");
        if (results is null || results.Value.GetArrayLength() == 0)
            return $"City '{city}' not found.";

        var location = results.Value[0];
        var lat = location.GetProperty("latitude").GetDouble();
        var lon = location.GetProperty("longitude").GetDouble();
        var name = location.GetProperty("name").GetString();

        var weatherUrl = $"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}&current_weather=true";
        var weather = await _httpClient.GetFromJsonAsync<JsonDocument>(weatherUrl, cancellationToken);
        var current = weather!.RootElement.GetProperty("current_weather");

        var temp = current.GetProperty("temperature").GetDouble();
        var windSpeed = current.GetProperty("windspeed").GetDouble();

        return $"Weather in {name}: {temp}°C, wind {windSpeed} km/h";
    }

    [McpServerTool, Description("Get a 7-day temperature forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        CancellationToken cancellationToken = default)
    {
        var geoUrl = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var geoResponse = await _httpClient.GetFromJsonAsync<JsonDocument>(geoUrl, cancellationToken);

        var results = geoResponse?.RootElement.GetProperty("results");
        if (results is null || results.Value.GetArrayLength() == 0)
            return $"City '{city}' not found.";

        var location = results.Value[0];
        var lat = location.GetProperty("latitude").GetDouble();
        var lon = location.GetProperty("longitude").GetDouble();

        var url = $"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}&daily=temperature_2m_max,temperature_2m_min&timezone=auto";
        var forecast = await _httpClient.GetFromJsonAsync<JsonDocument>(url, cancellationToken);
        var daily = forecast!.RootElement.GetProperty("daily");

        var dates = daily.GetProperty("time").EnumerateArray().Select(d => d.GetString()).ToList();
        var maxTemps = daily.GetProperty("temperature_2m_max").EnumerateArray().Select(t => t.GetDouble()).ToList();
        var minTemps = daily.GetProperty("temperature_2m_min").EnumerateArray().Select(t => t.GetDouble()).ToList();

        var lines = dates.Select((d, i) => $"  {d}: {minTemps[i]}°C – {maxTemps[i]}°C");
        return $"7-day forecast for {city}:\n{string.Join("\n", lines)}";
    }
}

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register HttpClient for DI — available to tool classes via constructor injection.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.Add("User-Agent", "McpWeatherServer/1.0");
});

// Register the MCP server with stdio transport.
// WithTools<T>() registers the tool class and wires up DI for its constructor params.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithTools<WeatherTools>();

await builder.Build().RunAsync();

